/* d_a_arrow_t60.h (WWHD, true 60 build; generated by tools/t60conv, 2026-11-18; procedures by hand):
 *d_a_arrow.cpp on a general step length (dt = 1/N). Decomp build only.
 *
 * Converted, the actor executes on every step with g_dt = 1/N; at dt = 1 (N = 1, the 30 Hz fallback, an unconverted
 * actor) every helper returns the original per-frame value (dt-1 check bit-exact). The helpers are the shared ones of
 * d/t60conv.h plus the frame-start latch ar60 below; d_a_arrow.cpp keeps thin calls only.
 *
 * Sites (tool):
 *     _execute  tmr  first-step AI-timer    mSparkleTimer counted on the frame's first step (the sparkle follows the player per step)
 *     _execute  tmr  first-step AI-timer    mBtkFrame counted on the frame's first step
 *     _execute  rnd  first-step AI-timer    the mBtkFrame start draw on the frame's first step, once per frame
 * Sites (by hand: the procedures sit behind the hand-expanded member-pointer dispatch, which the tool cannot resolve):
 *     _execute  misc 30 Hz visual-motion (2) the procedure dispatch under t60c::procBegin / procEnd: a procedure set on a step (setProc in
 *                           procWait / procMove / rebound / check_water_in) first runs its body on the next frame's
 *                           first step; the frame's remaining steps hold
 *     procWait  ord  14     the shot (fopAcM_GetParam == 1, set by the archer on one of its steps: MP use, speed, shoot
 *                           sound, the first AT capsule) on the tick30 step only, from the archer's frame-end hand
 *                           matrix (the hookshot's procWait form); the other steps only follow the hand
 *     procMove  ord  14/one-sweep-per-frame attack every decision of the frame on the tick30 step: the tick30 step restores the frame start
 *                           (current.pos, old.pos, latched on the first step) and runs the original frame: the AT-hit
 *                           reads (the tick30 collision Move's flags), the BG line check over the WHOLE frame segment
 *                           (old.pos -> frame end + speed / 4: no tunnelling through thin walls, the original's single
 *                           check), the water entry, the far-flight gravity / delete, the blur start and the AT capsule
 *                           (one registration per 30 Hz frame for the tick30 Move, the one-sweep-per-frame attack rule)
 *     procMove  mov  6      the in-between steps are visual only: current.pos = frame start + speed x (the frame's dt
 *                           so far) and the model matrix, capped at the wall the frame's flight stops at (a visual line
 *                           check on the first step into mLinChk, which the tick30 step sets anew); mModelMtx is the frame start's copy (taken on the first step,
 *                           as A takes it at the start of its execute); the blur spin (0x889) on the 30 Hz grid (30 Hz visual-motion)
 *     procReturn ord 14     the same form: gravity, the bounce line check / reflection, the water effect and the blur
 *                           fade on the tick30 step from the restored frame start; the in-between steps show the frame's
 *                           fall (speed with the frame's gravity) and spin (shape_angle.x + mSpinSpeedX x dt so far)
 *     procStop_BG    30 Hz visual-motion    on the tick30 step only (the 30 Hz form): shake timer, stop / blink timer, the moving
 *                           background's frame transform (dBgS_MoveBgTransPos once per frame, as the hookshot), the CO
 *                           sphere registration and its pick-up read (one per tick30 Move)
 *     procStop_Actor 8      the blur fade on the tick30 step; the matrix follows the hit actor's joint on every step
 *     setStopActorMatrix 8  the shake timer counted on the tick30 step (a visual counter), the shake read on every step
 *     procWater      30 Hz visual-motion    on the tick30 step only (the in-water timer and the delete at A's moment)
 *
 * Not in kT60Converted: the profile is added after the paired runs. */
#pragma once
#include "d/t60conv.h"

namespace ar60 {

/* the hand forms' switch: off at dt = 1 and in the negative-control build (T60C_NEGCTRL: every step runs the original
 * per-frame procedure, the form the tool's N-step spec negative control must reject) */
static inline bool on() {
#ifdef T60C_NEGCTRL
    return false;
#else
    return t60c::on();
#endif
}

/* the frame-start state of a moving arrow, latched on the frame's first step (several arrows fly at once: up to five,
 * l_count; a slot of an earlier frame is free) */
struct Start {
    u32 ea, tag;
    f32 px, py, pz;
    f32 ox, oy, oz;
    s16 ax;
    f32 span, cap;
    u32 mtxEa;     /* the model's base matrix (guest), 0: none */
    u32 mtx[12];   /* its words at the frame start */
};
enum { kSlots = 16 };
static Start s_start[kSlots];

static inline Start* find(const void* k, bool make) {
    const u32 ea = gabi::ea(k), tag = t60c::frameTag();
    Start* free_slot = 0;
    for (int i = 0; i < kSlots; i++) {
        Start& s = s_start[i];
        if (s.ea == ea && s.tag == tag)
            return &s;
        if (!free_slot && (s.ea == 0 || s.tag != tag))
            free_slot = &s;
    }
    if (!make)
        return 0;
    Start* s = free_slot ? free_slot : &s_start[ea % kSlots];
    s->ea = ea;
    s->tag = tag;
    return s;
}

enum Step { kOriginal = 0, kVisual = 1, kTick30 = 2 };

/* one step of a moving procedure (procMove / procReturn) whose whole frame is decided on the tick30 step.
 * pos / old / angleX: the actor's current.pos, old.pos, shape_angle.x; v: the frame's speed (the original's frame move);
 * spin: shape_angle.x's per-frame add (0: none); cap: the share of the frame move the in-between steps show at most
 * (procMove: where the frame's flight stops at a wall, so the arrow is not shown behind it for a step); mtx: the model's
 * base matrix (guest address, 0: none), which the in-between steps set for drawing: the tick30 step puts back its frame-start
 * words, so a frame whose original path sets no matrix (a delete) leaves A's matrix (N-step spec procMove input 1000019).
 *   kVisual   an in-between step (the first included): pos = frame start + v x the frame's dt so far, angleX likewise;
 *             the caller draws (model matrix) and returns
 *   kTick30   the tick30 step: pos, old and angleX are back at the frame start; the caller runs the original frame
 *   kOriginal off (dt = 1, the negative control) or not latched on this frame's first step: the original as it is */
template <class V, class A>
static inline int frameStep(const void* k, V* pos, V* old, A* angleX, f32 vx, f32 vy, f32 vz, s32 spin,
                            f32 cap = 1.0f, u32 mtx = 0) {
    if (!on())
        return kOriginal;
    Start* s = find(k, t60::first_step());
    if (!s)
        return kOriginal;
    if (t60::first_step()) {
        s->px = pos->x;
        s->py = pos->y;
        s->pz = pos->z;
        s->ox = old->x;
        s->oy = old->y;
        s->oz = old->z;
        s->ax = (s16)*angleX;
        s->span = 0.0f;
        s->cap = cap;
        s->mtxEa = mtx;
        for (int i = 0; mtx != 0 && i < 12; i++)
            s->mtx[i] = *gabi::at<be<u32>>(mtx + 4 * i);
    }
    if (t60::tick30()) {
        pos->x = s->px;
        pos->y = s->py;
        pos->z = s->pz;
        old->x = s->ox;
        old->y = s->oy;
        old->z = s->oz;
        *angleX = s->ax;
        for (int i = 0; s->mtxEa != 0 && s->mtxEa == mtx && i < 12; i++)
            *gabi::at<be<u32>>(mtx + 4 * i) = s->mtx[i];
        s->tag = ~s->tag;
        return kTick30;
    }
    s->span += t60::dt();
    const f32 shown = s->span < s->cap ? s->span : s->cap;
    pos->x = s->px + vx * shown;
    pos->y = s->py + vy * shown;
    pos->z = s->pz + vz * shown;
    if (spin != 0)
        *angleX = (s16)(s->ax + (s16)(s32)((f32)spin * s->span));
    return kVisual;
}

}  // namespace ar60
